// views/Notifications.jsx (or wherever it is)
import React from "react";
import { useSelector } from "react-redux";
// keep your existing all-in-one import style for consistency
import { GoPerson, BsTwitter, AiOutlineRetweet, AiOutlineHeart } from "react-icons/all";
import { BiMessageDetail } from "react-icons/all";

function Notifications() {
  const { data } = useSelector((state) => state.currentProfile);
  const notifications = data?.notifications || [];

  if (!notifications.length) return "No notifications yet";

  return notifications.map((n, idx) => {
    const line = (
      <>
        {/* Optional: show actor avatar/username if present */}
        {n.actor?.username ? <strong>@{n.actor.username}</strong> : null} {n.message}
      </>
    );

    switch (n.type) {
      case "follow":
        return (
          <div key={idx} className="notification display-flex align-items-c">
            <GoPerson />
            <p>{line}</p>
          </div>
        );
      case "like":
        return (
          <div key={idx} className="notification display-flex align-items-c">
            <AiOutlineHeart />
            <p>{line}</p>
          </div>
        );
      case "retweet":
        return (
          <div key={idx} className="notification display-flex align-items-c">
            <AiOutlineRetweet />
            <p>{line}</p>
          </div>
        );
      case "reply":
        return (
          <div key={idx} className="notification display-flex align-items-c">
            <BiMessageDetail />
            <p>{line}</p>
          </div>
        );
      default:
        return (
          <div key={idx} className="notification display-flex align-items-c">
            <BsTwitter />
            <p>{n.message}</p>
          </div>
        );
    }
  });
}

export default Notifications;
